export function formatWithdrawalAmount(lamports: number | null): string {
  if (lamports === null || lamports === undefined) return '—';
  const solAmount = lamports / 1_000_000_000;
  return `${solAmount.toFixed(4)} SOL`;
}

export function formatWithdrawalDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

export function truncateWithdrawalId(id: string): string {
  if (id.length <= 12) return id;
  return `${id.slice(0, 6)}...${id.slice(-4)}`;
}

export function getWithdrawalTimeElapsed(dateString: string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffDays > 0) return `${diffDays}d ago`;
  if (diffHours > 0) return `${diffHours}h ago`;
  if (diffMins > 0) return `${diffMins}m ago`;
  return 'just now';
}

export function isWithinPrivacyPeriod(withdrawalAvailableAt: string | undefined): boolean {
  if (!withdrawalAvailableAt) return true;
  return new Date(withdrawalAvailableAt) > new Date();
}
