/**
 * Sub-components for AdminWithdrawalQueue.
 *
 * Extracted to keep AdminWithdrawalQueue.tsx within the 500-line file budget.
 */

import type { AdminDepositItem } from '../../../types/deposit';
import {
  formatWithdrawalAmount,
  formatWithdrawalDate,
  getWithdrawalTimeElapsed,
  isWithinPrivacyPeriod,
  truncateWithdrawalId,
} from './AdminWithdrawalQueueHelpers';

// ---------------------------------------------------------------------------
// EarlyWithdrawalModal
// ---------------------------------------------------------------------------

interface EarlyWithdrawalModalProps {
  item: AdminDepositItem;
  processingId: string | null;
  onConfirm: (item: AdminDepositItem, force: true) => void;
  onCancel: () => void;
}

/**
 * Confirmation dialog shown before processing a withdrawal that is still
 * within its privacy period.
 */
export function EarlyWithdrawalModal({
  item,
  processingId,
  onConfirm,
  onCancel,
}: EarlyWithdrawalModalProps) {
  return (
    <div
      className="cedros-admin-modal-overlay"
      onClick={onCancel}
      onKeyDown={(e) => e.key === 'Escape' && onCancel()}
      role="dialog"
      aria-modal="true"
      aria-labelledby="early-withdrawal-title"
    >
      <div
        className="cedros-admin-modal cedros-admin-modal-warning"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={() => {}}
        role="document"
      >
        <h3 id="early-withdrawal-title" className="cedros-admin-modal-title">
          Early Withdrawal Warning
        </h3>
        <div className="cedros-admin-modal-content">
          <p className="cedros-admin-modal-warning-text">
            <strong>This deposit is still within its privacy period.</strong>
          </p>
          <p>
            Processing this withdrawal early may compromise user privacy. The privacy period exists
            to provide plausible deniability for deposits.
          </p>
          <p className="cedros-admin-modal-details">
            User: {truncateWithdrawalId(item.userId)}
            <br />
            Amount: {formatWithdrawalAmount(item.amountLamports)}
            <br />
            Available at:{' '}
            {item.withdrawalAvailableAt
              ? formatWithdrawalDate(item.withdrawalAvailableAt)
              : '—'}
          </p>
          <p>Are you sure you want to process this withdrawal early?</p>
        </div>
        <div className="cedros-admin-modal-actions">
          <button
            type="button"
            className="cedros-button cedros-button-outline"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="cedros-button cedros-button-danger"
            onClick={() => onConfirm(item, true)}
            disabled={processingId === item.id}
          >
            {processingId === item.id ? 'Processing...' : 'Process Early'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WithdrawalRow
// ---------------------------------------------------------------------------

interface WithdrawalRowProps {
  item: AdminDepositItem;
  processingId: string | null;
  processingAll: boolean;
  onItemClick?: (item: AdminDepositItem) => void;
  onProcess: (item: AdminDepositItem) => void;
}

/**
 * A single row in the withdrawal queue table.
 */
export function WithdrawalRow({
  item,
  processingId,
  processingAll,
  onItemClick,
  onProcess,
}: WithdrawalRowProps) {
  const withinPrivacyPeriod = isWithinPrivacyPeriod(item.withdrawalAvailableAt);
  const isProcessing = processingId === item.id;

  return (
    <div
      key={item.id}
      className={`cedros-admin-withdrawal-row ${withinPrivacyPeriod ? 'cedros-admin-withdrawal-row-early' : ''}`}
      onClick={() => onItemClick?.(item)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onItemClick?.(item);
        }
      }}
      role={onItemClick ? 'button' : undefined}
      tabIndex={onItemClick ? 0 : undefined}
    >
      <div className="cedros-admin-withdrawal-td" title={item.userId}>
        {truncateWithdrawalId(item.userId)}
      </div>
      <div className="cedros-admin-withdrawal-td">
        {formatWithdrawalAmount(item.amountLamports)}
      </div>
      <div className="cedros-admin-withdrawal-td">
        {item.withdrawalAvailableAt ? formatWithdrawalDate(item.withdrawalAvailableAt) : '—'}
      </div>
      <div className="cedros-admin-withdrawal-td cedros-admin-withdrawal-waiting">
        {item.withdrawalAvailableAt
          ? withinPrivacyPeriod
            ? 'In privacy period'
            : getWithdrawalTimeElapsed(item.withdrawalAvailableAt)
          : '—'}
      </div>
      <div className="cedros-admin-withdrawal-td cedros-admin-withdrawal-td-action">
        <button
          type="button"
          className={`cedros-button cedros-button-sm ${withinPrivacyPeriod ? 'cedros-button-warning' : 'cedros-button-primary'}`}
          onClick={(e) => {
            e.stopPropagation();
            onProcess(item);
          }}
          disabled={isProcessing || processingAll}
          title={
            withinPrivacyPeriod
              ? 'Early withdrawal (requires confirmation)'
              : 'Process this withdrawal'
          }
        >
          {isProcessing ? '...' : withinPrivacyPeriod ? 'Early' : 'Process'}
        </button>
      </div>
    </div>
  );
}
